                );
                let wrong = layout
                    .signature_owner(&parsed[0], target, &foreign_ty, &authored, &parsed)
                    .err()
                    .unwrap();
                let restored = layout
                    .signature_owner(&parsed[0], target, current_ty, &authored, &parsed)
                    .err()
                    .unwrap();
                same_diagnostics(&wrong, &restored);
